<?php $active_module='dashboard'; require_once __DIR__ . '/layout.php'; $u=$supplier_user; $pdo=db(); $properties=$pdo->prepare('SELECT COUNT(*) FROM properties WHERE supplier_id=?'); $properties->execute([$u['supplier_id']]); $propertyCount=(int)$properties->fetchColumn(); $roomTypes=$pdo->prepare("SELECT COUNT(*) FROM room_types rt JOIN properties p ON p.id=rt.property_id WHERE p.supplier_id=? AND rt.status='active'"); $roomTypes->execute([$u['supplier_id']]); $roomTypeCount=(int)$roomTypes->fetchColumn(); $insights=$pdo->prepare("SELECT priority,title,body FROM ai_insights WHERE supplier_id=? AND status='new' ORDER BY CASE priority WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END, id DESC LIMIT 3"); $insights->execute([$u['supplier_id']]); $icalHealth=$pdo->prepare("SELECT p.id, p.name, p.property_type, (SELECT COUNT(*) FROM ical_connections c WHERE c.property_id=p.id AND c.status='active') active_con, (SELECT COUNT(*) FROM ical_connections c WHERE c.property_id=p.id AND c.status<>'active') inactive_con, (SELECT MAX(c.last_sync_at) FROM ical_connections c WHERE c.property_id=p.id) last_sync_at, (SELECT COUNT(*) FROM ical_events e JOIN ical_connections c ON c.id=e.ical_connection_id WHERE c.property_id=p.id) block_count, (SELECT MAX(c.last_error) FROM ical_connections c WHERE c.property_id=p.id AND COALESCE(c.last_error,'')<>'') last_error FROM properties p WHERE p.supplier_id=? AND p.property_type IN ('villa','yacht') ORDER BY p.name"); $icalHealth->execute([$u['supplier_id']]); $icalHealthRows=$icalHealth->fetchAll(); $icalTotActive = 0; $icalTotInactive = 0; $icalProblemListings = 0; foreach ($icalHealthRows as $ic) { $icalTotActive += (int) $ic['active_con']; $icalTotInactive += (int) $ic['inactive_con']; $icTs = $ic['last_sync_at'] !== null ? strtotime((string) $ic['last_sync_at']) : 0; $icProblem = (int) $ic['active_con'] === 0 || $icTs === 0 || $icTs < time() - 30 * 86400 || (int) $ic['active_con'] > 0 && $icTs > 0 && $icTs < time() - 7 * 86400; if ($icProblem) $icalProblemListings++; } $chHealth=$pdo->prepare("SELECT c.id, c.display_name, c.channel_code, c.status, c.last_sync_at, c.last_error, (SELECT COUNT(*) FROM channel_sync_logs l WHERE l.channel_connection_id=c.id AND l.status='failed') fail_count FROM channel_connections c WHERE c.supplier_id=? ORDER BY c.status, c.display_name"); $chHealth->execute([$u['supplier_id']]); $chHealthRows=$chHealth->fetchAll(); $whqPending=0; $whqFailed24=0; try { $whqTbl=(bool)$pdo->query("SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='channel_sync_logs'")->fetchColumn(); if ($whqTbl) { $whq=$pdo->prepare("SELECT COUNT(*) FILTER (WHERE status='queued') pending, COUNT(*) FILTER (WHERE status='failed' AND created_at>=now()-interval '24 hours') failed24 FROM channel_sync_logs WHERE channel_connection_id IN (SELECT id FROM channel_connections WHERE supplier_id=?)"); $whq->execute([$u['supplier_id']]); $whqRow=$whq->fetch(); $whqPending=(int)($whqRow['pending']??0); $whqFailed24=(int)($whqRow['failed24']??0); } } catch (Throwable $e) {} $pendingMapCount=0;try{$rmTbl=(bool)$pdo->query("SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='channel_room_mappings'")->fetchColumn();$rmCol=$rmTbl&&(bool)$pdo->query("SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='channel_room_mappings' AND column_name='status'")->fetchColumn();$pmTbl=(bool)$pdo->query("SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='channel_rate_plan_mappings'")->fetchColumn();$pmCol=$pmTbl&&(bool)$pdo->query("SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='channel_rate_plan_mappings' AND column_name='status'")->fetchColumn();if($rmCol){$q=$pdo->prepare("SELECT COUNT(*) FROM channel_room_mappings m JOIN channel_connections c ON c.id=m.channel_connection_id WHERE c.supplier_id=? AND m.status='suggested'");$q->execute([$u['supplier_id']]);$pendingMapCount+=(int)$q->fetchColumn();}if($pmCol){$q=$pdo->prepare("SELECT COUNT(*) FROM channel_rate_plan_mappings p JOIN channel_connections c2 ON c2.id=p.channel_connection_id WHERE c2.supplier_id=? AND p.status='suggested'");$q->execute([$u['supplier_id']]);$pendingMapCount+=(int)$q->fetchColumn();}}catch(Throwable $e){$pendingMapCount=0;} supply_start('Günaydın, ' . explode(' ', $u['full_name'])[0], $active_module); ?>
<section class="stats"><article><span>AKTİF TESİS</span><b><?= $propertyCount ?></b><small>Satışa açık ürün</small></article><article><span>AKTİF ODA TİPİ</span><b><?= $roomTypeCount ?></b><small>Yayınlanmaya hazır</small></article><article><span>BUGÜNÜN REZERVASYONU</span><b>—</b><small>Pilot verisi bekleniyor</small></article><article class="accent"><span>NEXUS AI</span><b>3</b><small>İşlem önerisi</small></article><article><span>ONAY BEKLEYEN EŞLEŞTİRME</span><b><?= $pendingMapCount ?></b><small>Oda / fiyat planı eşleştirme önerisi</small></article></section><section class="panel" style="margin-top:18px"><div class="panel-title"><div><span>WEBHOOK KUYRUĞU</span><h2>Kanal bildirim işleme</h2></div><a href="/nexustraveltech/tedarikci/dagitim-merkezi">Dağıtım merkezi →</a></div><div class="availability-row"><div><b><?= $whqPending ?> bekleyen yük</b><span>Kanaldan gelen, henüz işlenmemiş bildirim</span></div><?= $whqPending > 0 ? '<strong style="color:#8a6100">⚠ Kuyrukta bekleme</strong>' : '<strong>Aktif</strong>' ?></div><div class="availability-row"><div><b><?= $whqFailed24 ?> başarısız (son 24 sa)</b><span>Otomatik yeniden deneme (maks. 3) sırasında</span></div><?= $whqFailed24 > 0 ? '<strong style="color:#b0301a">✗ Hata var</strong>' : '<strong>Aktif</strong>' ?></div></section><section class="dashboard-grid"><article class="panel availability"><div class="panel-title"><div><span>CANLI OPERASYON</span><h2>Satışa hazır envanter</h2></div><a href="/nexustraveltech/tedarikci/tesisler">Tesisleri yönet →</a></div><div class="availability-row"><div><b>NEXUS Pilot Hotel</b><span>Fethiye · Otel</span></div><strong>Aktif</strong></div><div class="availability-row"><div><b>Deluxe Sea View</b><span>18 ünite · 2 yetişkin</span></div><strong>Hazır</strong></div><div class="availability-row"><div><b>Family Suite</b><span>8 ünite · 4 yetişkin</span></div><strong>Hazır</strong></div></article><article class="panel ai-panel"><div class="panel-title"><div><span>NEXUS AI / ÖNCELİKLER</span><h2>Bugün neye bakmalı?</h2></div><a href="/nexustraveltech/tedarikci/yapay-zeka">Tüm öneriler →</a></div><?php foreach($insights as $insight): ?><div class="insight <?= htmlspecialchars($insight['priority']) ?>"><b><?= htmlspecialchars($insight['title']) ?></b><p><?= htmlspecialchars($insight['body']) ?></p></div><?php endforeach; ?></article></section><?php if ($icalHealthRows): ?><section class="panel" style="margin-top:18px"><div class="panel-title"><div><span>iCAL SAĞLIK DURUMU</span><h2>Takvim senkronizasyonu</h2></div><a href="/nexustraveltech/tedarikci/ical-takvimler">iCal takvimler →</a></div><div class="availability-row"><div><b><?= count($icalHealthRows) ?> ilan · <?= $icalTotActive ?> aktif / <?= $icalTotInactive ?> pasif bağlantı</b><span>Özet</span></div><?= $icalProblemListings > 0 ? '<strong style="color:#b0301a">' . $icalProblemListings . ' sorunlu ilan</strong>' : '<strong>Aktif</strong>' ?></div><?php foreach ($icalHealthRows as $ic): $icTs = $ic['last_sync_at'] !== null ? strtotime((string)$ic['last_sync_at']) : 0; $icOld30 = (int)$ic['active_con'] > 0 && ($icTs === 0 || $icTs < time() - 30 * 86400); $icStale7 = !$icOld30 && (int)$ic['active_con'] > 0 && $icTs > 0 && $icTs < time() - 7 * 86400; ?><div class="availability-row"><div><b><?= htmlspecialchars($ic['name']) ?></b><span><?= $ic['property_type'] === 'yacht' ? 'Yat' : 'Villa' ?> · <?= (int)$ic['active_con'] ?> aktif / <?= (int)$ic['inactive_con'] ?> pasif bağlantı · <?= (int)$ic['block_count'] ?> blok · son senkron <?= $ic['last_sync_at'] ? htmlspecialchars($ic['last_sync_at']) : 'hiç yok' ?><?= $ic['last_error'] ? ' · hata: ' . htmlspecialchars($ic['last_error']) : '' ?></span></div><?= (int)$ic['active_con'] > 0 ? ($icOld30 ? '<strong style="color:#b0301a">✗ Eski senkron (30+ gün)</strong>' : ($icStale7 ? '<strong style="color:#8a6100">⚠ Eski senkron</strong>' : '<strong>Aktif</strong>')) : '<strong style="color:#b0301a">Pasif</strong>' ?></div><?php endforeach; ?></section><?php endif; ?><?php if ($chHealthRows): ?><section class="panel" style="margin-top:18px"><div class="panel-title"><div><span>DAĞITIM SAĞLIK DURUMU</span><h2>Kanal bağlantıları</h2></div><span class="panel-title-actions"><a href="/nexustraveltech/tedarikci/dagitim-merkezi">Dağıtım & kanal merkezi →</a><?php if ($pendingMapCount > 0): ?><span class="map-pending-badge" title="Onay bekleyen oda / fiyat planı eşleştirme önerileri — Dağıtım & kanal merkezi → bölüm 3">⏳ <?= $pendingMapCount ?> onay bekleyen eşleştirme</span><?php endif; ?></span></div><?php foreach ($chHealthRows as $cc): $chTs = $cc['last_sync_at'] !== null ? strtotime((string)$cc['last_sync_at']) : 0; $chOld30 = $cc['status'] === 'active' && ($chTs === 0 || $chTs < time() - 30 * 86400); $chStale7 = !$chOld30 && $cc['status'] === 'active' && $chTs > 0 && $chTs < time() - 7 * 86400; $chErr = $cc['status'] === 'error'; ?><div class="availability-row"><div><b><?= htmlspecialchars($cc['display_name']) ?></b><span><?= htmlspecialchars($cc['channel_code']) ?> · durum: <?= htmlspecialchars($cc['status']) ?> · son senkron <?= $cc['last_sync_at'] ? htmlspecialchars($cc['last_sync_at']) : 'hiç yok' ?><?= (int)$cc['fail_count'] > 0 ? ' · <span style="color:#b0301a">' . (int)$cc['fail_count'] . ' başarısız iş</span>' : '' ?><?= $cc['last_error'] ? ' · hata: ' . htmlspecialchars($cc['last_error']) : '' ?></span></div><?= $chErr ? '<strong style="color:#b0301a">✗ Hata</strong>' : ($cc['status'] === 'active' ? ($chOld30 ? '<strong style="color:#b0301a">✗ Eski senkron (30+ gün)</strong>' : ($chStale7 ? '<strong style="color:#8a6100">⚠ Eski senkron</strong>' : '<strong>Aktif</strong>')) : '<strong style="color:#8a6100">' . ($cc['status'] === 'draft' ? 'Taslak' : 'Pasif') . '</strong>') ?></div><?php endforeach; ?></section><?php endif; ?><?php supply_end(); ?>
